<script setup>import{Link,router,usePage}from'@inertiajs/vue3';import AppLayout from'../../Layouts/AppLayout.vue';defineProps({cart:Object});const page=usePage(),money=v=>new Intl.NumberFormat('en-TZ',{style:'currency',currency:page.props.store.currency,maximumFractionDigits:0}).format(v||0);const update=(p,q)=>router.patch(`/cart/${p.slug}`,{quantity:q},{preserveScroll:true}),remove=p=>router.delete(`/cart/${p.slug}`,{preserveScroll:true});</script><template><AppLayout><div class="container-shell py-8"><h1 class="text-3xl font-black">Your cart</h1><div v-if="cart.items.length" class="mt-6 grid gap-6 lg:grid-cols-[1fr_340px]"><div class="grid gap-3"><div v-for="line in cart.items" :key="line.product.id" class="card flex gap-4 p-3"><img :src="line.product.image_url" class="h-24 w-24 rounded-[8px] object-cover"><div class="flex-1"><Link :href="`/products/${line.product.slug}`" class="font-black">{{line.product.name}}</Link><p class="mt-1 text-sm text-slate-500">{{money(line.unit_price)}}</p><div class="mt-3 flex items-center gap-2"><input :value="line.quantity" type="number" min="0" class="input w-20" @change="update(line.product,Number($event.target.value))"><button class="text-sm font-bold text-red-600" @click="remove(line.product)">Remove</button></div></div><b>{{money(line.line_total)}}</b></div></div><aside class="card h-fit p-5"><h2 class="font-black">Order summary</h2><div class="mt-4 space-y-2 text-sm"><div class="flex justify-between"><span>Subtotal</span><b>{{money(cart.subtotal)}}</b></div><div class="flex justify-between"><span>Delivery</span><b>{{money(cart.shipping)}}</b></div><div class="flex justify-between border-t pt-3 text-lg"><span>Total</span><b>{{money(cart.total)}}</b></div></div><Link href="/checkout" class="btn-primary mt-5 w-full">Checkout</Link></aside></div><div v-else class="card mt-6 p-10 text-center"><p class="text-slate-500">Your cart is empty.</p><Link href="/shop" class="btn-primary mt-4">Browse products</Link></div></div></AppLayout></template>
